{"code":"def transform(grid):
    H,W=len(grid),len(grid[0])
    for h in range(1,H+1):
      if H%h: continue
      for w in range(1,W+1):
        if W%w: continue
        blocks=[]
        for r in range(0,H,h):
          for c in range(0,W,w):
            blocks.append(tuple(tuple(row[c:c+w]) for row in grid[r:r+h]))
        # identify uniform background block, and a repeated nonuniform object
        uni=[b for b in blocks if len(set(x for row in b for x in row))==1]
        if not uni: continue
        bg=uni[0]
        non=[b for b in blocks if b!=bg]
        if non and len(set(non))==1 and len(non)>=2:
          return [list(x) for x in non[0]]
    return [row[:] for row in grid]"}

